<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Conway's Game of Life</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }

  body {
    background: #0d0d0d;
    color: #e0e0e0;
    font-family: 'Segoe UI', system-ui, sans-serif;
    display: flex;
    flex-direction: column;
    align-items: center;
    min-height: 100vh;
    padding: 20px;
  }

  h1 {
    font-size: 2rem;
    margin-bottom: 16px;
    background: linear-gradient(135deg, #00ff88, #00aaff);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    letter-spacing: 2px;
    text-transform: uppercase;
  }

  #controls {
    display: flex;
    gap: 12px;
    margin-bottom: 16px;
    flex-wrap: wrap;
    justify-content: center;
  }

  button {
    padding: 10px 22px;
    border: 2px solid;
    border-radius: 8px;
    font-size: 0.95rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.15s ease;
    letter-spacing: 0.5px;
    text-transform: uppercase;
    background: transparent;
  }

  #step {
    border-color: #00aaff;
    color: #00aaff;
  }
  #step:hover { background: #00aaff22; }

  #play {
    border-color: #00ff88;
    color: #00ff88;
  }
  #play:hover { background: #00ff8822; }
  #play.running {
    border-color: #ff6644;
    color: #ff6644;
    background: #ff664422;
  }

  #random {
    border-color: #cc88ff;
    color: #cc88ff;
  }
  #random:hover { background: #cc88ff22; }

  #clear {
    border-color: #ff4466;
    color: #ff4466;
  }
  #clear:hover { background: #ff446622; }

  #info {
    font-size: 0.85rem;
    color: #666;
    margin-bottom: 10px;
  }

  #life-wrapper {
    border: 2px solid #333;
    border-radius: 4px;
    box-shadow: 0 0 30px #00ff8811, 0 0 60px #00aaff08;
    cursor: crosshair;
  }

  #life {
    display: block;
  }

  #gen-counter {
    margin-top: 12px;
    font-size: 0.9rem;
    color: #888;
    letter-spacing: 1px;
  }

  #gen-counter span {
    color: #00ff88;
    font-weight: bold;
  }
</style>
</head>
<body>

<h1>Game of Life</h1>

<div id="controls">
  <button id="step">⏭ Step</button>
  <button id="play">▶ Play</button>
  <button id="random">🎲 Random</button>
  <button id="clear">🗑 Clear</button>
</div>

<div id="info">Click or drag on the grid to toggle cells</div>

<div id="life-wrapper">
  <canvas id="life"></canvas>
</div>

<div id="gen-counter">Generation: <span id="gen-num">0</span></div>

<script>
(function() {
  const COLS = 60;
  const ROWS = 60;
  const CELL_SIZE = 10; // px per cell
  const CANVAS_W = COLS * CELL_SIZE;
  const CANVAS_H = ROWS * CELL_SIZE;

  const canvas = document.getElementById('life');
  canvas.width = CANVAS_W;
  canvas.height = CANVAS_H;
  const ctx = canvas.getContext('2d');

  const genNumEl = document.getElementById('gen-num');
  const playBtn = document.getElementById('play');

  // Grid storage: flat array, row-major
  let grid = new Uint8Array(COLS * ROWS);
  let generation = 0;
  let running = false;
  let animId = null;
  let lastTime = 0;
  const INTERVAL = 100; // ms between generations when playing

  function idx(x, y) {
    return y * COLS + x;
  }

  function getCell(x, y) {
    if (x < 0 || x >= COLS || y < 0 || y >= ROWS) return 0;
    return grid[idx(x, y)];
  }

  function setCell(x, y, v) {
    if (x < 0 || x >= COLS || y < 0 || y >= ROWS) return;
    grid[idx(x, y)] = v ? 1 : 0;
    draw();
  }

  function stepGen() {
    const next = new Uint8Array(COLS * ROWS);
    for (let y = 0; y < ROWS; y++) {
      for (let x = 0; x < COLS; x++) {
        let neighbors = 0;
        for (let dy = -1; dy <= 1; dy++) {
          for (let dx = -1; dx <= 1; dx++) {
            if (dx === 0 && dy === 0) continue;
            neighbors += getCell(x + dx, y + dy);
          }
        }
        const alive = grid[idx(x, y)];
        if (alive) {
          next[idx(x, y)] = (neighbors === 2 || neighbors === 3) ? 1 : 0;
        } else {
          next[idx(x, y)] = (neighbors === 3) ? 1 : 0;
        }
      }
    }
    grid = next;
    generation++;
    genNumEl.textContent = generation;
    draw();
  }

  function clearAll() {
    grid = new Uint8Array(COLS * ROWS);
    generation = 0;
    genNumEl.textContent = generation;
    draw();
  }

  function randomize() {
    for (let i = 0; i < grid.length; i++) {
      grid[i] = Math.random() < 0.3 ? 1 : 0;
    }
    generation = 0;
    genNumEl.textContent = generation;
    draw();
  }

  // Colors
  const BG_COLOR = '#0d0d0d';
  const GRID_COLOR = '#1a1a1a';
  const CELL_COLOR_ALIVE = '#00ff88';
  const CELL_GLOW = 'rgba(0,255,136,0.15)';

  function draw() {
    // Background
    ctx.fillStyle = BG_COLOR;
    ctx.fillRect(0, 0, CANVAS_W, CANVAS_H);

    // Grid lines
    ctx.strokeStyle = GRID_COLOR;
    ctx.lineWidth = 0.5;
    for (let x = 0; x <= COLS; x++) {
      ctx.beginPath();
      ctx.moveTo(x * CELL_SIZE, 0);
      ctx.lineTo(x * CELL_SIZE, CANVAS_H);
      ctx.stroke();
    }
    for (let y = 0; y <= ROWS; y++) {
      ctx.beginPath();
      ctx.moveTo(0, y * CELL_SIZE);
      ctx.lineTo(CANVAS_W, y * CELL_SIZE);
      ctx.stroke();
    }

    // Alive cells
    for (let y = 0; y < ROWS; y++) {
      for (let x = 0; x < COLS; x++) {
        if (grid[idx(x, y)]) {
          const px = x * CELL_SIZE;
          const py = y * CELL_SIZE;
          // Glow effect
          ctx.fillStyle = CELL_GLOW;
          ctx.fillRect(px - 1, py - 1, CELL_SIZE + 2, CELL_SIZE + 2);
          // Cell body
          ctx.fillStyle = CELL_COLOR_ALIVE;
          ctx.fillRect(px + 1, py + 1, CELL_SIZE - 2, CELL_SIZE - 2);
        }
      }
    }
  }

  // Animation loop
  function loop(timestamp) {
    if (!running) return;
    if (timestamp - lastTime >= INTERVAL) {
      stepGen();
      lastTime = timestamp;
    }
    animId = requestAnimationFrame(loop);
  }

  function startPlay() {
    running = true;
    playBtn.textContent = '⏸ Pause';
    playBtn.classList.add('running');
    lastTime = 0;
    animId = requestAnimationFrame(loop);
  }

  function stopPlay() {
    running = false;
    playBtn.textContent = '▶ Play';
    playBtn.classList.remove('running');
    if (animId) cancelAnimationFrame(animId);
  }

  // Button events
  document.getElementById('step').addEventListener('click', () => {
    if (running) stopPlay();
    stepGen();
  });

  playBtn.addEventListener('click', () => {
    if (running) stopPlay();
    else startPlay();
  });

  document.getElementById('random').addEventListener('click', randomize);
  document.getElementById('clear').addEventListener('click', clearAll);

  // Mouse interaction
  let isPainting = false;
  let paintValue = 1;

  function getCellFromEvent(e) {
    const rect = canvas.getBoundingClientRect();
    const scaleX = CANVAS_W / rect.width;
    const scaleY = CANVAS_H / rect.height;
    const cx = Math.floor((e.clientX - rect.left) * scaleX / CELL_SIZE);
    const cy = Math.floor((e.clientY - rect.top) * scaleY / CELL_SIZE);
    return { x: cx, y: cy };
  }

  canvas.addEventListener('mousedown', (e) => {
    e.preventDefault();
    const { x, y } = getCellFromEvent(e);
    if (x < 0 || x >= COLS || y < 0 || y >= ROWS) return;
    paintValue = grid[idx(x, y)] ? 0 : 1;
    isPainting = true;
    setCell(x, y, paintValue);
  });

  canvas.addEventListener('mousemove', (e) => {
    if (!isPainting) return;
    const { x, y } = getCellFromEvent(e);
    if (x < 0 || x >= COLS || y < 0 || y >= ROWS) return;
    setCell(x, y, paintValue);
  });

  window.addEventListener('mouseup', () => { isPainting = false; });

  // Touch support
  canvas.addEventListener('touchstart', (e) => {
    e.preventDefault();
    const touch = e.touches[0];
    const { x, y } = getCellFromEvent(touch);
    if (x < 0 || x >= COLS || y < 0 || y >= ROWS) return;
    paintValue = grid[idx(x, y)] ? 0 : 1;
    isPainting = true;
    setCell(x, y, paintValue);
  }, { passive: false });

  canvas.addEventListener('touchmove', (e) => {
    e.preventDefault();
    if (!isPainting) return;
    const touch = e.touches[0];
    const { x, y } = getCellFromEvent(touch);
    if (x < 0 || x >= COLS || y < 0 || y >= ROWS) return;
    setCell(x, y, paintValue);
  }, { passive: false });

  canvas.addEventListener('touchend', () => { isPainting = false; });

  // Expose window.life API
  window.life = {
    get w() { return COLS; },
    get h() { return ROWS; },
    get(x, y) {
      return getCell(x, y);
    },
    set(x, y, v) {
      setCell(x, y, v);
    },
    step() {
      stepGen();
    },
    clear() {
      clearAll();
    }
  };

  // Initial draw
  draw();
})();
</script>
</body>
</html>
